cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
    },

    GetKuangShowParent:function(){
        return cc.find("Canvas/safe_node/slots/top_kuang");
    },

    playWinAnimation(){
        let wild_node = cc.vv.gameData.GetSlotsScript().getWildNode(this._symbolIdx, this._reelIdx);
        if(wild_node && wild_node.active){
            wild_node.getComponent(sp.Skeleton).setAnimation(0,"animation2",true)
        }else {
            this._super();
        }
    },

})
