    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    update(dt) {
        this._super(dt)
        // 转轴停止，闪电击中动画都播放完成
        if (this._spinEnd && this._hitSdList.length <= 0) {
            this._spinEnd = false;
            this.onSpinEndAction();
        }
    },
