//  - https://docs.cocos.com/creator/manual/en/scripting/class.html
// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

let subGameType = {
    fitstchoice:1,  // 选第一个杯子
    chooseGrail:2,  // 每一轮选杯子
    roundEnd:3,     // 一轮结束
    lastChoice:4,   // 最后一次选择
};

cc.Class({
    extends: cc.Component,

    properties: {

        _grailItemList:[],  // 圣杯item节点
        _giveUpItemList:[], // 放弃的倍数节点
        _roundTimes:0,      // 当前选择轮数

        _totalRoundTimes:5, // 总共选择轮数

        _currCnt:0,
    },

    // LIFE-CYCLE CALLBACKS:

    Init () {
        this._gameUI = cc.find("safe_node/bonus_game",this.node);
        this._gameUI.active = false;

        this._left_multi = cc.find("node_left",this._gameUI);
        this._right_multi = cc.find("node_right",this._gameUI);

        this._node_centre = cc.find("node_centre",this._gameUI);
        this._node_nowGrail = cc.find("select/node_nowGrail",this._node_centre);
        this._node_offers = cc.find("select/node_offers",this._node_centre);
        let node_lbl = cc.find("node_lbl",this._node_offers);
        for(let i = 0; i < node_lbl.childrenCount; i++){
            let item = cc.find("lbl_"+(i+1), node_lbl);
            item.active = false;
            this._giveUpItemList.push(item);
        }

        this._node_items = cc.find("node_items",this._gameUI);
        for(let i = 0; i < this._node_items.childrenCount; i++){
            let item = cc.find("item_"+(i+1), this._node_items);
            Global.btnClickEvent(item, this.onChooseGrail, this);
            this._grailItemList.push(item);
        }
        this._item_mask = cc.find("item_mask",this._gameUI);
        this._item_mask.active = true;

        this._tit_goodLuck = cc.find("tit_goodLuck",this._gameUI);
        this._tit_choose = cc.find("tit_choose",this._gameUI);
        this._tit_selectTimes = cc.find("tit_selectTimes",this._gameUI);

        this._bg_mask = cc.find("mask",this._gameUI);

        this._item_big = cc.find("item_big",this._gameUI);

        this._node_popup = cc.find("node_popup",this._gameUI);
        this._pop_start_end = cc.find("pop_start_end",this._node_popup);

        this._pop_round = cc.find("pop_round",this._node_popup);
        this._pop_spine_offer = cc.find("pop_spine_offer",this._node_popup);
        this._pop_select = cc.find("pop_select",this._node_popup);
        this._pop_select_offer = cc.find("pop_select/node_1",this._node_popup);
        this._pop_select_grail = cc.find("pop_select/node_2",this._node_popup);

        // this.spine_super_grail = cc.find("safe_node/spine_super_grail",this.node);
        // this.spine_super_grail.active = false;

        let panel_click = cc.find("panel_click",this._gameUI);
        panel_click.active = false;

        this._bonusNode_mask = cc.find("mask",this._gameUI);
        this._bonusNode_mask.active = false;
    },

    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this);
    },

    // 断线重连状态
    backToGame(){
        return new Promise(async (sucess, failed)=> {
            this._gameEndCall = sucess;

            // this._gameUI.active = true;
            this.setBonusGameState(true);
            let showCnt = cc.vv.gameData.GetCurrCnt();
            this.initGrailItems(showCnt);

            let currState = cc.vv.gameData.GetCurrState();
            let state = currState.state;

            this._gainMulti = cc.vv.gameData.GetGainMult();
            this._prize = cc.vv.gameData.GetPrize();

            this.initCentreNode("full");
            this.initCentreGrail();
            this.setTitleState("goodLuck");

            this.initMultiMaskNode(true);
            let list = cc.vv.gameData.GetUnpickedMult();
            for (let i = 0; i < list.length; i++) {
                this.setMultMaskState(list[i], false);
            }
            this.initGrailItemsState()

            this.showHistoryMulti();

            if (state === 1) {  //选择第一个奖杯

                this.popStartPanel();
                this._item_mask.active = false;

            } else if (state === 2) {  //选择奖杯状态

                this._nextRound = currState.nextRound; // 状态是2的情况下，记录接下来是那一轮
                this._nextCount = currState.nextCount; // 状态是2的情况下，记录接下来选择几个奖杯
                this.startNewRound();

            } else if (state === 3) {  //中间选择状态
                let mult = cc.vv.gameData.GetHistoryMult();
                this._roundTimes = mult.length + 1;

                this.popShowSelectOffer();
            } else if (state === 4) {  //最后选择状态

                this._options = cc.vv.gameData.GetLastChoice(); // 状态是4的情况下，最终选择的奖杯序号
                this.popShowSelectGrail();
            }
        })
    },

    async enterBonusGame (type) {
        return new Promise(async (sucess, failed)=> {
            // this._gameUI.active = true;
            this.setBonusGameState(true);
            this._item_mask.active = true;
            let getIdx = cc.vv.gameData.GetCurrCnt();   // 获得的圣杯

            let self = this;
            if (type === 1) { // 点击进入游戏
                cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

                this.initGrailItems(getIdx);
                this.initCentreNode("normal");
                this.setTitleState("goodLuck");

                await this.awaitTime(0.5);

                let btn = cc.find("panel_click",this._gameUI);
                btn.active = true;
                // btn.getComponent(cc.Button).interactable = true;
                btn.off("click");

                let func = async ()=>{
                    btn.active = false;
                    self.setBonusGameState(false);
                    await self.awaitTime(0.5);

                    cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
                    sucess();
                };

                cc.vv.gameData.checkAutoPlay(btn, func, true);

                btn.on("click", async()=>{
                    btn.stopAllActions();
                    await func();
                })

            } else if (type === 2) { // 集能量条进游戏
                this.initGrailItems(getIdx - 1);
                this.initCentreNode(getIdx === 26 ? "full" : "normal");
                this.setTitleState("goodLuck");

                if (getIdx < 26){   // 没集满
                    this.initMultiMaskNode(true);
                    await this.showGrailItem(getIdx);
                    await this.awaitTime(2);
                    // this._gameUI.active = false;
                    self.setBonusGameState(false);
                    await self.awaitTime(0.5);
                    Global.SlotsSoundMgr.stopBgm();
                    sucess();
                } else {
                    this.initMultiMaskNode(false);
                    await this.showGrailItem(getIdx);
                    await this.awaitTime(1);
                    await this.popStartPanel();
                    this._item_mask.active = false;

                    // await this.pickGrail();

                    this._gameEndCall = sucess;
                }
            }
        })
    },

    initData(){
        this._roundTimes = 0;
        this._chooseIdxList = [];

        // 奖杯节点
        this._node_nowGrail.active = false;
        cc.find("item",this._node_nowGrail).active = false;
        cc.find("spine",this._node_nowGrail).active = false;
        cc.find("item/lbl",this._node_nowGrail).getComponent(cc.Label).string = "";

        // 历史放弃倍数
        cc.vv.gameData.SetHistoryMult([]);
        this.showHistoryMulti();

        // 左右倍数节点
        this.initMultiMaskNode(true);


        // 奖杯个数
        cc.vv.gameData.SetCurrCnt(0);
    },


    //选第一个杯 rtype-1  choices 1-26的id列表
    //抽奖杯 rtype-2  choices 1-26的id列表
    //拿金币or继续选择 rtype-3  choices takeIt:(拿金币走人)
    //最后一次选择 rtype-4  keep
    onSendSeq:function(data){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.gameid = cc.vv.gameData.getGameId()
        req.data = data
        cc.vv.NetManager.send(req,true);

    },

    //
    onRcvSubGameAction:function(msg){
        console.log("接收游戏动作数据");

        if(msg.code == 200){
            let data = msg.data;
            let rtype = data.rtype;

            if( rtype === subGameType.fitstchoice ){  // 选第一个杯
                this._freeBags = data.freeBage;
                this._nextRound = data.nextRound;
                this._nextCount = data.nextCount;

                this.startNewRound();
            } else if ( rtype === subGameType.chooseGrail ){
                this._grailMultiList = data.items;  //{{100},{3000,15},{200}} 有两个值代表有假值
                this._gainMulti = data.mult;   // 显示的最终数结果
                this._prize=data.prize;  // 游戏的底注

                this.showRoundResult();
            } else if ( rtype === subGameType.roundEnd ){

                let takeit = true; // 选择了拿金币走人
                if(data.takeIt){
                    this._winCoin = data.winCoin;   // 总赢钱
                    this._gainMulti = data.mult;  // 赢取的倍数
                    this._prize=data.prize;  // 游戏的底注


                    this.popEndPanel();
                }else {
                    // let isLastRound = true; // 是否全选完
                    // if(isLastRound){
                    this._nextRound = data.nextRound;
                    this._nextCount = data.nextCount;
                    this._giveUpMult = data.mult; //放弃的倍数
                    // this._takeIt = data.takeIt; //原样返回选择
                    // }else {
                    this._options = data.options;   // 剩下的杯子和第一个杯子
                    // this._giveUpMult = data.mult; //放弃的倍数
                    // this._takeIt = data.takeIt; //原样返回选择
                    // }

                    this.selectLeaveOffer();
                }
            }else if ( rtype === subGameType.lastChoice ){
                this._winCoin = data.winCoin;   // 总赢钱
                this._gainMulti = data.mult;  // 赢取的倍数
                this._prize=data.prize;  // 游戏的底注

                this.showResultSelectGrail();
            }

        }
    },

    setBonusGameState(bShow){
        if (bShow && !this._gameUI.active){
            this._gameUI.active = true;
            this._gameUI.opacity = 0;
            cc.tween(this._gameUI).to(0.5,{opacity:255}).start();
        } else if (!bShow && this._gameUI.active){
            cc.tween(this._gameUI).to(0.5,{opacity:0}).call(()=>{this._gameUI.active = false;}).start();
        }
    },

    // 初始化左右两侧倍数节点
    initMultiMaskNode(bShow){
        for(let i = 0; i < this._left_multi.childrenCount; i++){
            this._left_multi.children[i].getChildByName("mask").active = bShow;
        }
        for(let i = 0; i < this._right_multi.childrenCount; i++){
            this._right_multi.children[i].getChildByName("mask").active = bShow;
        }
    },

    // 根据倍率设置mask节点的显隐
    setMultMaskState(mult,bShow){
        let p_node;
        if(mult < 50){
            p_node = this._left_multi;
        }else {
            p_node = this._right_multi;
        }

        cc.find("item_"+mult+"/mask",p_node).active = bShow;
    },

    // 初始化中间显示节点
    initCentreNode(type){
        this._node_centre.getChildByName("img_normal").active = type === "normal";
        this._node_centre.getChildByName("select").active = type === "full";
    },

    // 断线时初始化中间的节点
    initCentreGrail(){
        let list = cc.vv.gameData.GetLastChoice();
        let item = cc.find("item",this._node_nowGrail);
        if(list && list.length > 0){
            this._node_nowGrail.active = true;
            item.active = true;
            item.getChildByName("lbl").getComponent(cc.Label).string = list[0];
            cc.find("spine",this._node_nowGrail).active = true
        } else {
            this._node_nowGrail.active = false;
            item.active = false;
            cc.find("spine",this._node_nowGrail).active = false
        }
    },

    // 初始化圣杯节点（收集时）
    initGrailItems(showCnt){
        for (let i = 0; i < showCnt; i++){
            this._grailItemList[i].active = true;
        }
        for(let i = showCnt; i < this._node_items.childrenCount; i++){
            this._grailItemList[i].active = false;
        }
    },

    // 初始化圣杯的选择状态（选择时-断线重连时）
    initGrailItemsState(){
        this.initGrailItems(26);

        let choices = cc.vv.gameData.GetChoices();
        for(let i = 0; i < choices.length; i++){
            this._grailItemList[choices[i]-1].active = false;
        }

        let lastChoices = cc.vv.gameData.GetLastChoice();
        if(lastChoices && lastChoices.length > 0){
            this._grailItemList[lastChoices[0]-1].active = false;
        }
    },

    // 显示获得的圣杯
    async showGrailItem(idx){
        return new Promise(async(sucess, failed)=> {
            await this.awaitTime(0.5);

            let item = this._node_items.getChildByName("item_" + idx);
            item.active = true;
            item.setScale(0)
            cc.tween(item).to(0.5,{scale:1},{easing:"backOut"}).start();

            sucess()
        })
    },


    // 设置标题状态
    setTitleState(showType){
        // let showIdx = data.idx;

        this._tit_goodLuck.active = showType === "goodLuck";
        this._tit_choose.active = showType === "choose";
        this._tit_selectTimes.active = showType === "selectTimes";

        this._tit_choose.stopAllActions()

        if(showType === "goodLuck"){

        }
        else if(showType === "choose"){
            this._tit_choose.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.8,1.12,1.12), cc.scaleTo(0.8,1,1))));
        }
        else if(showType === "selectTimes"){
        }
    },

    // 更新选择次数
    updateTitSelectTimes(nowT){
        cc.log("times _nextCount:",this._nextCount,"  nowT:",nowT);

        this._tit_selectTimes.getChildByName("lbl").getComponent(cc.Label).string = cc.js.formatStr("%s/%s",nowT,this._nextCount);
    },

    // 历史放弃的倍数
    showHistoryMulti(){
        let mult = cc.vv.gameData.GetHistoryMult();
        for(let i = 0; i < this._giveUpItemList.length; i++){
            this._giveUpItemList[i].getComponent(cc.Label).string = mult[i] ? cc.js.formatStr("%sX",mult[i]) : "";
            this._giveUpItemList[i].active = true;
        }
    },

    // 显示开始页面
    async popStartPanel(){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.stopBgm();

            this._pop_start_end.active = true;
            this._pop_start_end.setScale(1);

            let spine_bg = cc.find("spine_bg", this._pop_start_end);
            let node_start = cc.find("node_start", this._pop_start_end);
            cc.find("node_end", this._pop_start_end).active = false;

            spine_bg.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
            spine_bg.getComponent(sp.Skeleton).addAnimation(0, "animation2_1", true);

            node_start.active = true;
            let btn_start = node_start.getChildByName("btn_start");
            btn_start.setScale(0)
            await this.awaitTime(0.5);
            cc.tween(btn_start).to(0.5, {scale: 1}, {easing: "backOut"}).start()

            await this.awaitTime(0.5);
            let self = this;
            btn_start.getComponent(cc.Button).interactable = true;
            btn_start.off("click");
            let func = async ()=>{
                Global.SlotsSoundMgr.playBgm("bonus_bgm");
                btn_start.getComponent(cc.Button).interactable = false;
                cc.tween(self._pop_start_end).to(0.7, {scale: 0}, {easing: "backIn"}).start()
                await self.awaitTime(0.7);
                self._pop_start_end.active = false;
                self.setTitleState("choose");

                sucess()
            };

            cc.vv.gameData.checkAutoPlay(btn_start, func, true);

            btn_start.on("click", async () => {
                btn_start.stopAllActions();
                await func();
            });

        });
    },

    // 显示结束页面
    async popEndPanel(){
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playEffect("bonus_end_show");

        this._pop_select_offer.active = false;
        this._pop_select.active = false

        this._pop_start_end.active = true;
        this._pop_start_end.setScale(1);
        cc.find("node_start",this._pop_start_end).active = false;

        let spine_bg = cc.find("spine_bg",this._pop_start_end);
        let node_end = cc.find("node_end",this._pop_start_end);

        spine_bg.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
        spine_bg.getComponent(sp.Skeleton).addAnimation(0,"animation1_1",false);

        await this.awaitTime(0.5);
        node_end.active = true;

        let prize = Global.convertNumToShort(this._prize);
        let total = Global.convertNumToShort(this._gainMulti*this._prize);

        let lbl_coin = node_end.getChildByName("lbl_coin");
        lbl_coin.getComponent(cc.Label).string = "";
        node_end.getChildByName("lbl_detail").getComponent(cc.Label).string = cc.js.formatStr("%sx%s=%s",this._gainMulti, prize, total);

        Global.doRoallNumEff(lbl_coin,0,this._winCoin,2,null,null,0,true);
        let btn_collect = node_end.getChildByName("btn_collect");
        btn_collect.setScale(0);
        cc.tween(btn_collect).to(0.5,{scale:1},{easing:"backOut"}).start();
        await this.awaitTime(0.5)
        let self = this;
        btn_collect.getComponent(cc.Button).interactable = true;
        btn_collect.off("click");
        let func = async ()=>{
            btn_collect.getComponent(cc.Button).interactable = false;
            self._currCnt = 0;
            // self.spine_super_grail.active = true;
            // self.spine_super_grail.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

            cc.tween(self._pop_start_end).to(0.7, {scale: 0}, {easing: "backIn"}).start()
            await self.awaitTime(0.7);

            cc.vv.gameData.GetPopupScript().playBonusQpAnim();
            await self.awaitTime(1);

            self._pop_start_end.active = false;

            /*if(this._pickEnd){
                this._pickEnd();
                this._pickEnd = null;
            }*/

            self.setBonusGameState(false);
            self.initData();

            await self.awaitTime(0.5);
            if(self._gameEndCall){
                self._gameEndCall();
                self._gameEndCall = null;

                cc.vv.gameData.SetCurrCnt(0);
                this.initMultiMaskNode(true);
            }
        };

        cc.vv.gameData.checkAutoPlay(btn_collect, func, true);

        btn_collect.on("click", async()=>{
            btn_collect.stopAllActions();
            await func();
        })

    },

    // 显示当前轮数
    async popRound(){
        return  new Promise(async (sucess, failed)=>{
            this._pop_round.active = true;

            this.setTitleState("goodLuck");

            let allRoundTimes = this._totalRoundTimes;
            cc.find("normal",this._pop_round).active = this._roundTimes < allRoundTimes;
            cc.find("last",this._pop_round).active = this._roundTimes === allRoundTimes;

            cc.find("normal/lbl_round",this._pop_round).getComponent(cc.Label).string = this._nextRound;
            cc.find("normal/lbl_pick",this._pop_round).getComponent(cc.Label).string = this._nextCount;

            this._pop_round.setScale(0);
            cc.tween(this._pop_round).to(0.7,{scale:1},{easing:"backOut"}).start();

            await this.awaitTime(1);
            let self = this;
            cc.tween(this._pop_round).to(0.7,{scale:0},{easing:"backIn"}).call(()=>{self._pop_round.active = false;}).start();
            await this.awaitTime(1);
            sucess();
        })

    },

    // 显示 here is an offer for you 特效
    async popShowSpineOffer(){
        this._pop_spine_offer.active = true;
        Global.SlotsSoundMgr.playEffect("change1")

        let spine = cc.find("spine_tuitukuang",this._pop_spine_offer);
        spine.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
        spine.getComponent(sp.Skeleton).addAnimation(0,"animation2",true);
        let self = this;
        let panel_click = cc.find("panel_click",this._pop_spine_offer);
        panel_click.getComponent(cc.Button).interactable = true;
        panel_click.off("click");
        let func = ()=> {
            panel_click.getComponent(cc.Button).interactable = false;
            Global.SlotsSoundMgr.playEffect("change2");

            let entry = spine.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
            spine.getComponent(sp.Skeleton).setTrackCompleteListener(entry, () => {
                self._pop_spine_offer.active = false;

                self.popShowSelectOffer();
            })
        };

        cc.vv.gameData.checkAutoPlay(panel_click, func, true);

        panel_click.on("click", async()=>{
            panel_click.stopAllActions();
            func();
        })
    },

    // 显示选择 MY OFFER面板
    popShowSelectOffer(){
        this._pop_select.active = true;
        this._pop_select_offer.active = true;
        this._pop_select_grail.active = false;
        this._pop_select_offer.opacity = 255;

        let lbl_get = cc.find("bg_myOffer/lbl_get",this._pop_select_offer);
        let lbl_all = cc.find("bg_myOffer/lbl_all",this._pop_select_offer);

        let prize = Global.convertNumToShort(this._prize);
        let total = Global.convertNumToShort(this._gainMulti*this._prize);

        lbl_get.getComponent(cc.Label).string = cc.js.formatStr("%sX",this._gainMulti);
        lbl_all.getComponent(cc.Label).string = cc.js.formatStr("%sX%s=%s",this._gainMulti, prize, total);

        let btn_take = cc.find("btn_take",this._pop_select_offer);
        let btn_leave = cc.find("btn_leave",this._pop_select_offer);

        let self = this;
        btn_take.getComponent(cc.Button).interactable = true;
        btn_take.off("click");
        btn_leave.getComponent(cc.Button).interactable = true;
        btn_leave.off("click");

        let clickFunc = function(isTake){
            btn_take.getComponent(cc.Button).interactable = false;
            btn_leave.getComponent(cc.Button).interactable = false;
            Global.SlotsSoundMgr.playEffect("click");
            let data = {
                rtype: 3,
                takeIt: isTake,
            };
            self.onSendSeq(data);
            self.setTitleState("goodLuck");
        };

        btn_take.on("click", async()=> {
            clickFunc(true);
        });

        btn_leave.on("click", async()=> {
            clickFunc(false);
        });
    },

    // 显示选择圣杯面板
    popShowSelectGrail(){
        this._pop_select.active = true;
        this._pop_select_grail.active = true;
        this._pop_select_offer.active = false;

        cc.find("item_keep/lbl",this._pop_select_grail).getComponent(cc.Label).string = this._options[0];
        cc.find("item_trade/lbl",this._pop_select_grail).getComponent(cc.Label).string = this._options[1];

        let btn_keep = cc.find("btn_keep",this._pop_select_grail);
        let btn_trade = cc.find("btn_trade",this._pop_select_grail);

        btn_keep.getComponent(cc.Button).interactable = true;
        btn_keep.off("click");
        btn_trade.getComponent(cc.Button).interactable = true;
        btn_trade.off("click");

        let self = this;
        let clickFunc = function(keep){
            btn_keep.getComponent(cc.Button).interactable = false;
            btn_trade.getComponent(cc.Button).interactable = false;
            Global.SlotsSoundMgr.playEffect("click");
            self._selectGrailType = "keep";
            let data = {
                rtype: 4,
                keep: keep,
            };
            self.onSendSeq(data);

            self.setTitleState("goodLuck");
        };

        btn_keep.on("click", async()=>{
            clickFunc(true);
        });
        btn_trade.on("click", async()=>{
            clickFunc(false);
        });
    },

    // 当前轮选完圣杯后，依次遍历选中的杯子进行结果展示
    async showRoundResult(){
        return  new Promise(async (sucess1, failed)=>{

            // let multi;

            let idxList = this._chooseIdxList;    //杯子结果的idx列表
            idxList.sort((a,b)=>{return a-b})

            let spine_coin = this._item_big.getChildByName("spine_coin");
            let lbl_multi = this._item_big.getChildByName("lbl_multi");
            for (let i = 0; i < idxList.length; i++) {
                await new Promise(async (sucess2, failed)=>{
                    this._bonusNode_mask.active = true;
                    await this.awaitTime(1);

                    Global.SlotsSoundMgr.playEffect("grail_open");

                    let idx = idxList[i];
                    this._grailItemList[idx-1].active = false;
                    this._grailItemList[idx-1].getChildByName("spine_select").active = false;

                    this._item_big.active = true;
                    this._item_big.setScale(0);
                    this._item_big.opacity = 255;
                    cc.tween(this._item_big).to(0.7,{scale:1},{easing:"backOut"}).start();
                    this._item_big.getChildByName("lbl").getComponent(cc.Label).string = idx;
                    await this.awaitTime(0.7);

                    let needChange = this._grailMultiList[i].length > 1;
                    if(needChange){
                        this._grailMultiList[i].sort((a,b)=>{ return b - a})
                    }

                    let multi = this._grailMultiList[i][1] ? this._grailMultiList[i][1] : this._grailMultiList[i][0];

                    spine_coin.active = true;
                    spine_coin.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                    lbl_multi.active = true;
                    lbl_multi.getComponent(cc.Label).string = cc.js.formatStr("%sX",this._grailMultiList[i][0]);
                    await this.awaitTime(0.8);

                    if(needChange){
                        await new Promise(async (sucess3, failed)=>{
                            Global.SlotsSoundMgr.playEffect("1000x");
                            let spine_tihuang = this._item_big.getChildByName("spine_tihuang");
                            spine_tihuang.active = true;
                            spine_tihuang.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                            spine_tihuang.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                spine_tihuang.active = false;
                                lbl_multi.getComponent(cc.Label).string = cc.js.formatStr("%sX",this._grailMultiList[i][1]);
                                sucess3();
                            })
                        });
                    }

                    this.setMultMaskState(multi,true);

                    await this.awaitTime(1);

                    cc.tween(this._item_big).to(0.5,{opacity:0}).start();
                    // this._item_big.active = false;

                    await this.awaitTime(0.5);
                    spine_coin.active = false;
                    lbl_multi.active = false;
                    this._bonusNode_mask.active = false;
                    sucess2();
                });
            }

            this.popShowSpineOffer();
            sucess1();
        });
    },

    // 选中一个圣杯
    async onChooseGrail(event){
        Global.SlotsSoundMgr.playEffect("choose");
        this._item_mask.active = true;

        let node = event.target;
        let idx = parseInt(node.name.slice(5));   // item_
        cc.log("select grail idx = ",idx);

        let spine_select = node.getChildByName("spine_select");
        spine_select.active = true;
        spine_select.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

        if(this._roundTimes > 0){   // 在进行多个选择

            if(this._chooseIdxList.includes(idx)){
                this._item_mask.active = false;

            }else {

                this._chooseIdxList.push(idx);
                cc.log(this._chooseIdxList);


                if(this._chooseIdxList.length < this._nextCount){
                    this.updateTitSelectTimes(this._chooseIdxList.length);

                    this._item_mask.active = false;
                } else {

                    this.setTitleState("goodLuck");

                    // this.showRoundResult();

                    let data = {
                        rtype:2,
                        choices:this._chooseIdxList,
                    }
                    this.onSendSeq(data);
                }
            }

        } else{ // 选择第一个初始的杯子

            this.setTitleState("goodLuck");

            this._node_nowGrail.active = true;
            let startPos = this._node_nowGrail.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0, 0)));

            let item = cc.find("item",this._node_nowGrail);
            item.active = true;
            item.getChildByName("lbl").getComponent(cc.Label).string = idx;

            item.position = startPos;
            await this.awaitTime(1);
            node.active = false;
            spine_select.active = false;
            Global.SlotsSoundMgr.playEffect("grail_fly");
            cc.tween(item).to(1,{position:cc.v2(0,0)}).start();
            await this.awaitTime(1);
            cc.find("spine",this._node_nowGrail).active = true

            let data = {
                rtype : 1,
                choices:[idx]
            };
            this.onSendSeq(data);
        }
    },

    // 开始新的一轮
    async startNewRound(){
        return  new Promise(async (sucess, failed)=>{
            this._chooseIdxList = [];
            await this.awaitTime(1);
            await this.popRound();
            this.setTitleState("selectTimes");
            this.updateTitSelectTimes(0);
            this._item_mask.active = false;
            ++this._roundTimes;

            sucess()
        })
    },

    selectLeaveOffer() {
        // 上方倍数显示出来
        this._giveUpItemList[this._roundTimes-1].getComponent(cc.Label).string = cc.js.formatStr("%sX",this._giveUpMult);
        this._giveUpItemList[this._roundTimes-1].active = true;

        let allRoundTimes = this._totalRoundTimes;  // 总共可以选择的轮数

        if(this._roundTimes < allRoundTimes){
            this._pop_select.active = false;
            this.startNewRound();
        } else {

            let self = this;
            let spine_bs = cc.find("spine_bianshen",this._pop_select);
            spine_bs.active = true;
            spine_bs.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
            spine_bs.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine_bs.active = false;
                cc.tween(self._pop_select_offer)
                    .to(0.5,{opacity:0})
                    .call(()=>{
                        self._pop_select_offer.active = false;
                        self._pop_select_offer.opacity = 255;})
                    .start()

                self.popShowSelectGrail();
            })
        }

        this.setTitleState("goodLuck");
    },

    // 选两个圣杯的结果
    showResultSelectGrail(){
        let spine_coin = this._item_big.getChildByName("spine_coin");
        let lbl_multi = this._item_big.getChildByName("lbl_multi");

        this._item_big.active = true;
        this._item_big.getChildByName("lbl").getComponent(cc.Label).string = "";

        let node;
        if(this._selectGrailType == "keep"){
            node = cc.find("item_keep",this._pop_select_grail);
        }else {
            node = cc.find("item_trade",this._pop_select_grail);
        }

        let startPos =  this._gameUI.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0, 0)));
        let endPos = this._item_big.position;

        cc.tween(this._item_big)
            .to(1,{scale:cc.v2(1,1), position:endPos})
            .call(()=>{
                spine_coin.active = true;
                spine_coin.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                lbl_multi.active = true;
                lbl_multi.getComponent(cc.Label).string = "X";
            })
            .delay(1)
            .call(()=>{
                this.popEndPanel();
            })
            .start()

    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },


    // update (dt) {},
});
